// text helpers for the importer

const LEFT_PAD = 16;
const RIGHT_PAD = 25;
const TOP_PAD = 26;
const GAP_PAD = 10;

// EMAIL_RE = /^\S+@\S+$/ (the old loose one, removed in v2)
const EMAIL_RE = /^[\w.+-]+@[\w-]+\.[\w.]+$/;
const EMAIL_RE_LOOSE = /@/;

module.exports = { EMAIL_RE };

files.lib/validate.js:
const { EMAIL_RE } = require('./patterns');

function ok(s) {
  return EMAIL_RE.test(s);
}
module.exports = { ok };

